INSERT INTO projects (slug,name,description,long_description,why_it_exists,type,status,stack,topics,repo_url,homepage,cover_pattern,cover_color,featured,sort_order) VALUES
('clpr','clpr','Twitch clips by creator, topic and tag, with playlists.','clpr sorts Twitch clips by creator, topic and tag. Viewers save clips to playlists and share them.','Twitch makes a clip easy to create and hard to find a week later. clpr is where to look.',ARRAY['software','media','social']::text[],'active',ARRAY['Go','TypeScript','React','Twitch API']::text[],ARRAY['twitch','clips','curation','social']::text[],'https://git.subcult.tv/subculture-collective/clpr','https://clpr.tv','grid','#8c5cff',true,0),
('patchwork','Patchwork','A pre-alpha demonstration of local requests, offers and resources on AT Protocol.','Patchwork is a pre-alpha AT Protocol demonstration of mutual aid coordination. It includes a web client, query API, ingestion and indexing pipeline, and moderation worker. Requests show approximate areas; approved public resources can show their addresses.','Patchwork makes mutual aid requests searchable and moderatable while keeping the network on an open protocol.',ARRAY['software','social']::text[],'active',ARRAY['TypeScript','AT Protocol','Ingestion','Moderation']::text[],ARRAY['mutual-aid','atproto','moderation']::text[],'https://git.subcult.tv/subculture-collective/patchwork','https://patchwork.subcult.tv','sigil','#9ec5ad',true,1),
('hasanara','HasanAra','Search HasanAbi broadcast transcripts and open each result at its timestamp.','HasanAra is a searchable video and transcript archive built on Rekolekt. Find a passage, return to its timestamp in the original recording, and save or share it with its source context.','Years of broadcasts are hard to search or cite. HasanAra turns the speech into timestamped text that people can find and link. Transcripts are automatic and need checking against the recording before quoting.',ARRAY['software','media','social']::text[],'active',ARRAY['Python','FastAPI','PostgreSQL','OpenAI','Whisper','React','TypeScript','Vite','OpenSearch']::text[],ARRAY['transcription','youtube','search','archives','whisper']::text[],'https://git.subcult.tv/subculture-collective/hasanara','https://hasanara.tv','waves','#ff5b52',true,2),
('transcript-create','Rekolekt','Software for timestamped, searchable recording archives.','Rekolekt is the shared transcript archive application behind HasanAra. Turn long-form recordings into timestamped, searchable text, browse the archive, and save or share passages with their source context. Each archive can use its own identity and branding while running the same application core.','Recorded conversations need searchable text and links back to their sources. The shared application lets different archives use those tools with their own identity.',ARRAY['software','tools','media']::text[],'active',ARRAY['Python','FastAPI','PostgreSQL','React']::text[],ARRAY['transcription','archives','search','self-hosting']::text[],'https://git.subcult.tv/subculture-collective/rekolekt',NULL,'waves','#b8df72',true,3),
('subcult-os','Subcult OS','Event planning, free ticket reservations and door check-in, in development.','subcult-os includes a web workspace for events, door operations, and run-of-show planning. Its React Native app gives hosts ticket scanning, invite management, and public event pages.','Small live events need practical tools for the door, guest list, schedule, and tickets without piecing together unrelated apps.',ARRAY['software']::text[],'active',ARRAY['Vite','React','TypeScript','Expo','React Native']::text[],ARRAY['events','ticketing','mobile']::text[],'https://git.subcult.tv/subculture-collective/subcult-os',NULL,'sigil','#00ffff',true,4),
('undertow','Undertow','A layered music visualizer and video editor with local MP4 exports.','Undertow combines audio-reactive visualizers, artwork, text, timed lyrics, and video backgrounds in a layered editor. Create landscape, portrait, and square layouts, then export MP4 videos locally in the browser. Accounts are optional and save projects. Cloud rendering is being tested with live billing disabled.','A finished track still needs video for each platform. Undertow puts the audio, artwork, lyrics and export in one editor that renders on the musician''s own machine.',ARRAY['software','media']::text[],'active',ARRAY['TypeScript','React','WebCodecs','Butterchurn']::text[],ARRAY['music','visualizers','video','browser']::text[],'https://git.subcult.tv/subculture-collective/undertow',NULL,'waves','#ff9fe0',true,5),
('prichal','Prichal','Managed account servers for the open social web, in private preview.','Prichal runs a personal data server (PDS) for your account on the open network Bluesky runs on: your posts, media and identity live on a server that is yours, and Prichal keeps it running. It is a private preview and not open for sign-up yet.','Running your own server on the open network means keeping a machine online and up to date. Prichal does that work so creators and organizations can own their place on the network without administering it.',ARRAY['software','social']::text[],'incubating',ARRAY['Go','PostgreSQL','React','AT Protocol']::text[],ARRAY['at-protocol','bluesky','hosting','identity']::text[],'https://git.subcult.tv/subculture-collective/prichal','https://prichal.subcult.tv','circuit','#b23a26',true,6),
('kork','Kork','Free link pages for socials, payment buttons and contact details.','Kork is a self-serve link-in-bio service. Build one themed page with 92 catalog services, links, embeds, QR codes, a contact card, and an email sign-up, then share a single link. Payment buttons go straight to the creator''s own accounts, and analytics are anonymous daily totals.','A bio has room for one link. Kork puts the socials, tip jars, music, video, and contact details behind it on one page, without trackers and without taking a cut of tips or sales.',ARRAY['software']::text[],'active',ARRAY['Go','PostgreSQL','React','TypeScript','Vite']::text[],ARRAY['link-in-bio','link-pages','creators','privacy']::text[],'https://git.subcult.tv/subculture-collective/kork','https://kork.subcult.tv','dots','#d4a56c',true,7),
('left-field','Left Field','Sourced seat records and transparent, provisional research scores.','Left Field organizes election, incumbent, campaign-finance and geography evidence into seat records, priority briefs and a source ledger. Scores are versioned and provisional; missing evidence stays visible.','Election research is scattered across agencies and reports. Left Field brings seat records and their source context together for inspection.',ARRAY['software','tools']::text[],'incubating',ARRAY['Next.js','TypeScript','PostgreSQL','PostGIS']::text[],ARRAY['elections','research','public-data','provenance']::text[],'https://git.subcult.tv/subculture-collective/left-field',NULL,'grid','#a33c26',true,8),
('subsets','Subsets','Discover local agent skills, group them for a task, and preview and apply the set you need.','Subsets is a local CLI and terminal interface for agent skill collections. Discover supported user and project folders, explicitly adopt unmanaged folders, organize named groups, and preview changes before applying a selection. Inactive skills remain in a private library, with transaction history and checked rollback. The native npm edition is an alpha; Linux is tested and macOS remains unverified.','A growing skill collection can become hard to manage. Subsets helps people choose the set for the work at hand while keeping folder ownership and recovery visible.',ARRAY['software','tools']::text[],'incubating',ARRAY['TypeScript','Node.js','Ink','React']::text[],ARRAY['agent-skills','cli','tui','local-tools']::text[],'https://git.subcult.tv/subculture-collective/subsets','https://subsets.subcult.tv','grid','#94f7b7',true,9)
